insert into tenants (slug, name, plan) values ('seed-store', 'StarShop Demo', 'starter')
  on conflict (slug) do nothing;

insert into branches (tenant_id, name, region, comuna)
select id, 'Sucursal Centro', 'RM', 'Santiago' from tenants where slug = 'seed-store'
and not exists (select 1 from branches b join tenants t on t.id = b.tenant_id where t.slug = 'seed-store' and b.name = 'Sucursal Centro');
insert into branches (tenant_id, name, region, comuna)
select id, 'Sucursal Norte', 'RM', 'Quilicura' from tenants where slug = 'seed-store'
and not exists (select 1 from branches b join tenants t on t.id = b.tenant_id where t.slug = 'seed-store' and b.name = 'Sucursal Norte');

